-- Bryce-Canyon-Nationalpark
INSERT INTO public.destinations (name, slug, country, region, continent, hero_image, short_description, long_description, ai_summary, best_travel_time, ideal_duration, travel_type, quick_facts, highlights, insider_tips, faq, seo_title, seo_description, affiliate_search_intent, car_rental_recommended, similar_destinations, llmo_entities, llmo_answer_block, llmo_quick_answer, canonical_url, open_graph_image, twitter_image, open_graph_title, open_graph_description, twitter_title, twitter_description, status)
VALUES ($t$Bryce-Canyon-Nationalpark$t$, $t$bryce-canyon$t$, $t$Vereinigte Staaten (USA)$t$, $t$Utah (USA-Südwesten)$t$, $t$Nordamerika$t$, $t$/images/destinations/bryce-canyon-hero.jpg$t$, $t$Magischer Nationalpark in Utah mit tausenden leuchtend orangeroten Felsnadeln (Hoodoos), die im großen Amphitheater wie ein versteinertes Heer aufragen.$t$, $t$Der Bryce-Canyon-Nationalpark im Süden Utahs ist trotz seines Namens kein klassischer Canyon, sondern eine Reihe gewaltiger natürlicher Amphitheater, gefüllt mit tausenden filigranen Felsnadeln, den sogenannten Hoodoos. Diese leuchtend orangeroten, von Erosion geformten Steinsäulen ragen dicht an dicht empor und ergeben besonders bei Sonnenaufgang ein unwirkliches, glühendes Farbenspiel. Das größte und bekannteste ist das Bryce Amphitheater, das man von Aussichtspunkten wie Sunrise Point, Sunset Point, Inspiration Point und Bryce Point überblickt. Wanderwege wie der Navajo Loop und der Queen's Garden Trail führen mitten zwischen die Hoodoos hinab und bieten ein einzigartiges Erlebnis. Da der Park auf über 2.400 Metern Höhe liegt, ist es hier auch im Sommer angenehm kühl, und im Winter verwandelt Schnee die roten Felsen in eine Märchenlandschaft. Als ausgewiesener Dark Sky Park bietet Bryce zudem einen der klarsten Sternenhimmel der USA. Bryce lässt sich ideal mit dem nahen Zion-Nationalpark zu einer Südwesten-Rundreise verbinden.$t$, $t$Der Bryce-Canyon-Nationalpark in Utah ist berühmt für seine tausenden leuchtend orangeroten Felsnadeln (Hoodoos), die im großen Bryce Amphitheater aufragen. Hoch gelegen, angenehm kühl und ein ausgezeichneter Dark Sky Park, eignet er sich ideal als Teil eines Südwesten-Roadtrips und für Wander- und Fotoreisen; für die Einreise gelten die USA-Bestimmungen mit ESTA.$t$, $t$Mai bis September mit mildem Wetter sind ideal; dank der Höhenlage bleibt es auch im Sommer angenehm kühl. Im Winter ist der Park geöffnet und besonders fotogen, wenn Schnee auf den roten Hoodoos liegt.$t$, $t$1 bis 2 Tage, oft als Teil eines Südwesten-Roadtrips$t$, ARRAY[$t$Naturreise$t$,$t$Nationalparks$t$,$t$Roadtrip$t$,$t$Wandern$t$,$t$Fotoreise$t$,$t$Sternenbeobachtung$t$,$t$Familien$t$]::text[], $j${"currency":"US-Dollar (USD)","language":"Englisch","flightTime":"Kein Direktflug zum Park; ab Deutschland ca. 11 bis 12 Stunden in die USA plus Anschluss/Fahrt. Nächste Flughäfen: Las Vegas (LAS, rund 4 Stunden Fahrt), St. George (SGU, rund 2 Stunden) und Cedar City (CDC, rund 1,5 Stunden)","timezone":"Mountain Time (UTC−7; im Sommer UTC−6), rund acht Stunden hinter MEZ","visa":"Wie für die USA: kein Visum für Touristen (bis 90 Tage), aber elektronischer Reisepass und kostenpflichtige ESTA-Genehmigung erforderlich","bestMonths":"Mai bis September"}$j$::jsonb, $j$["Hoodoos – die tausenden leuchtend orangeroten Felsnadeln des Parks","Bryce Amphitheater – das größte und spektakulärste Amphitheater","Sunrise Point und Sunset Point – beste Aussichten und Wanderzugänge","Inspiration Point und Bryce Point – weite Panoramablicke über die Hoodoos","Navajo Loop und Queen's Garden Trail – Wanderung hinab zwischen die Felsnadeln","Sonnenaufgang – wenn die Hoodoos in leuchtenden Farben erglühen","Sternenhimmel – ausgewiesener Dark Sky Park mit hervorragender Sicht","Scenic Drive bis Rainbow Point – Panoramastraße mit weiteren Aussichten"]$j$::jsonb, $j$["Der Sonnenaufgang am Sunrise oder Sunset Point ist das absolute Highlight – dann glühen die Hoodoos in intensivem Orange und Rot.","Die Kombination aus Navajo Loop und Queen's Garden Trail ist die beliebteste Runde, um mitten zwischen den Felsnadeln durch das Amphitheater zu wandern.","Wegen der Höhenlage von über 2.400 Metern ist es auch im Sommer morgens und abends kühl – eine Jacke und Sonnenschutz gehören ins Gepäck, und im Frühjahr ist noch Schnee möglich.","Als International Dark Sky Park bietet Bryce einen außergewöhnlich klaren Sternenhimmel; im Sommer gibt es oft Ranger-geführte Astronomieprogramme."]$j$::jsonb, $j$[{"question":"Wann ist die beste Reisezeit für den Bryce-Canyon-Nationalpark?","answer":"Am angenehmsten sind die Monate Mai bis September. Dank der Höhenlage bleibt es selbst im Sommer kühl. Im Winter ist der Park geöffnet und besonders reizvoll, wenn Schnee auf den roten Hoodoos liegt, allerdings können dann manche Wege gesperrt sein."},{"question":"Was sind Hoodoos?","answer":"Hoodoos sind schlanke, durch Erosion und Frostsprengung geformte Felsnadeln aus farbigem Sandstein. Im Bryce Canyon stehen sie in besonders großer Zahl und dichter Anordnung, was die einzigartige Landschaft des Parks ausmacht."},{"question":"Wie reist man zum Bryce Canyon an?","answer":"Es gibt keinen Flughafen direkt am Park. Üblich ist ein Flug in die USA mit Ziel Las Vegas (rund 4 Stunden Fahrt), St. George oder Cedar City. Von dort fährt man mit dem Mietwagen weiter, meist im Rahmen eines Südwesten-Roadtrips."},{"question":"Braucht man am Bryce Canyon einen Mietwagen?","answer":"Ja, für die Anreise ist ein Mietwagen sehr empfehlenswert, da der Park abgelegen liegt. In der Hauptsaison gibt es zudem einen kostenlosen Shuttlebus, der die wichtigsten Aussichtspunkte im Amphitheater anbindet."},{"question":"Brauche ich für den Bryce Canyon ein Visum?","answer":"Es gelten die Einreisebestimmungen der USA: Für touristische Aufenthalte bis 90 Tage ist kein Visum nötig, aber ein elektronischer Reisepass und eine vorab beantragte, kostenpflichtige ESTA-Genehmigung. Details finden sich auf der USA-Seite."},{"question":"Was kostet der Eintritt in den Bryce-Canyon-Nationalpark?","answer":"Für ein privates Fahrzeug gilt ein mehrtägiges Eintrittsticket. Wer mehrere US-Nationalparks besucht, fährt mit dem Jahrespass „America the Beautiful“ oft günstiger, der den Eintritt in alle Nationalparks abdeckt."},{"question":"Welche Wanderung lohnt sich im Bryce Canyon?","answer":"Besonders beliebt ist die kombinierte Runde aus Navajo Loop und Queen's Garden Trail, die vom Rand hinab zwischen die Hoodoos und wieder hinaufführt. Sie gilt als eine der schönsten kurzen Wanderungen der US-Nationalparks."},{"question":"Muss man mit Höhe und kühlem Wetter rechnen?","answer":"Ja, der Park liegt auf über 2.400 Metern Höhe. Dadurch ist es auch im Sommer angenehm kühl, morgens und nachts sogar kalt. Warme Kleidung und Sonnenschutz sind ratsam, im Frühjahr und Herbst ist Schnee möglich."},{"question":"Ist der Bryce Canyon für Familien geeignet?","answer":"Ja, der Park ist familienfreundlich. Die Aussichtspunkte sind leicht erreichbar, und einfachere Wege ins Amphitheater eignen sich auch für Kinder. An den ungesicherten Canyonrändern ist jedoch Vorsicht geboten."},{"question":"Wie viele Tage sollte man für den Bryce Canyon einplanen?","answer":"Für die wichtigsten Aussichtspunkte und eine Wanderung reichen 1 bis 2 Tage. Der Park lässt sich gut mit dem nahen Zion-Nationalpark und weiteren Zielen im Südwesten zu einer Rundreise verbinden."}]$j$::jsonb, $t$Bryce-Canyon-Nationalpark: Hoodoos, Wandern & beste Reisezeit$t$, $t$Dein Besuch im Bryce-Canyon-Nationalpark in Utah: tausende leuchtend rote Hoodoos, das Bryce Amphitheater, die besten Aussichtspunkte und Wanderwege. Beste Reisezeit, Anreise, Tipps und Highlights im Überblick.$t$, $t$Bryce Canyon Reise buchen, Flug nach Las Vegas, Mietwagen USA-Südwesten, Hotel Bryce Canyon, Bryce Canyon Touren und Wanderungen, Rundreise Südwesten USA Nationalparks$t$, true, $j$["zion","grand-canyon","monument-valley"]$j$::jsonb, ARRAY[$t$Bryce-Canyon-Nationalpark$t$,$t$Utah$t$,$t$Hoodoos$t$,$t$Bryce Amphitheater$t$,$t$Sunrise Point$t$,$t$Sunset Point$t$,$t$Inspiration Point$t$,$t$Bryce Point$t$,$t$Navajo Loop$t$,$t$Queen's Garden Trail$t$,$t$Thor's Hammer$t$,$t$Rainbow Point$t$,$t$Dark Sky Park$t$,$t$Las Vegas$t$,$t$USA-Südwesten$t$]::text[], $t$Der Bryce-Canyon-Nationalpark in Utah ist berühmt für seine tausenden leuchtend orangeroten Felsnadeln (Hoodoos), die dicht an dicht im großen Bryce Amphitheater aufragen und besonders bei Sonnenaufgang glühen. Hoch gelegen und angenehm kühl, ist er zudem ein ausgewiesener Dark Sky Park mit hervorragendem Sternenhimmel und eignet sich ideal als Teil eines Südwesten-Roadtrips, oft kombiniert mit dem nahen Zion. Für die Einreise gelten die USA-Bestimmungen mit elektronischem Reisepass und ESTA.$t$, $t$Der Bryce-Canyon-Nationalpark in Utah begeistert mit tausenden leuchtend roten Felsnadeln (Hoodoos) im großen Amphitheater, am schönsten bei Sonnenaufgang.$t$, $t$https://www.apearound.de/reiseziele/bryce-canyon$t$, $t$/images/destinations/bryce-canyon.jpg$t$, $t$/images/destinations/bryce-canyon.jpg$t$, $t$Bryce-Canyon-Nationalpark: Hoodoos, Wandern & beste Reisezeit$t$, $t$Dein Besuch im Bryce-Canyon-Nationalpark in Utah: tausende leuchtend rote Hoodoos, das Bryce Amphitheater, die besten Aussichtspunkte und Wanderwege. Beste Reisezeit, Anreise, Tipps und Highlights im Überblick.$t$, $t$Bryce-Canyon-Nationalpark: Hoodoos, Wandern & beste Reisezeit$t$, $t$Dein Besuch im Bryce-Canyon-Nationalpark in Utah: tausende leuchtend rote Hoodoos, das Bryce Amphitheater, die besten Aussichtspunkte und Wanderwege. Beste Reisezeit, Anreise, Tipps und Highlights im Überblick.$t$, $t$draft$t$)
ON CONFLICT (slug) DO NOTHING;

-- China
INSERT INTO public.destinations (name, slug, country, region, continent, hero_image, short_description, long_description, ai_summary, best_travel_time, ideal_duration, travel_type, quick_facts, highlights, insider_tips, faq, seo_title, seo_description, affiliate_search_intent, car_rental_recommended, similar_destinations, llmo_entities, llmo_answer_block, llmo_quick_answer, canonical_url, open_graph_image, twitter_image, open_graph_title, open_graph_description, twitter_title, twitter_description, status)
VALUES ($t$China$t$, $t$china$t$, $t$Volksrepublik China$t$, $t$Ostasien$t$, $t$Asien$t$, $t$/images/destinations/china-hero.jpg$t$, $t$Riesiges Reich der Mitte mit der Chinesischen Mauer, der Terrakotta-Armee, futuristischen Megastädten, Karstlandschaften und Pandas – für Deutsche jetzt visumfrei.$t$, $t$China ist ein Land der Superlative und Gegensätze, das jahrtausendealte Kultur mit atemberaubender Moderne verbindet. Das berühmteste Wahrzeichen ist die Chinesische Mauer, die sich über tausende Kilometer durch das Land zieht. In der Hauptstadt Peking beeindrucken die Verbotene Stadt, der Tian'anmen-Platz und der Himmelstempel, während in Xi'an die weltberühmte Terrakotta-Armee schlummert. Shanghai präsentiert sich als futuristische Megacity mit spektakulärer Skyline am Bund. Naturwunder wie die Karstberge entlang des Li-Flusses bei Guilin und Yangshuo, die schwebenden Felsen von Zhangjiajie oder die Gelben Berge (Huangshan) zählen zu den schönsten Landschaften Asiens. In Chengdu kann man die berühmten Großen Pandas bestaunen. Dank des hervorragenden Hochgeschwindigkeitszugnetzes lassen sich die enormen Distanzen erstaunlich bequem überwinden. Besonders erfreulich: Für deutsche Reisende ist die Einreise derzeit visumfrei. China ist ideal für Kultur-, Rundreise- und Naturerlebnisse – erfordert aber wegen Sprache, Bezahlsystemen und Internet etwas Vorbereitung.$t$, $t$China ist ein riesiges Reiseland in Ostasien mit der Chinesischen Mauer, der Terrakotta-Armee in Xi'an, Megastädten wie Peking und Shanghai, den Karstlandschaften bei Guilin und den Pandas in Chengdu. Es ist für deutsche Reisende derzeit visumfrei (bis 30 Tage) und dank Hochgeschwindigkeitszügen gut zu bereisen, erfordert aber Vorbereitung bei Sprache, mobilem Bezahlen und Internet.$t$, $t$Frühling (April bis Mai) und Herbst (September bis November) mit mildem Wetter sind ideal; der Hochsommer ist heiß und schwül, der Winter im Norden kalt. Die großen Feiertage sollte man wegen des Andrangs meiden.$t$, $t$2 bis 3 Wochen$t$, ARRAY[$t$Rundreise$t$,$t$Kulturreise$t$,$t$Städtereise$t$,$t$Naturreise$t$,$t$Geschichtsreise$t$,$t$Abenteuer$t$]::text[], $j${"currency":"Renminbi / Yuan (CNY); China ist weitgehend bargeldlos, üblich sind die Bezahl-Apps Alipay und WeChat Pay","language":"Chinesisch (Hochchinesisch/Mandarin); Englisch ist wenig verbreitet","flightTime":"ca. 10 bis 12 Stunden ab Deutschland im Direktflug (Peking, Shanghai)","timezone":"Landesweit einheitlich UTC+8, sieben Stunden vor MEZ","visa":"Für deutsche Staatsbürger derzeit visumfrei bis 30 Tage (Regelung gilt bis 31.12.2026); nötig sind ein 6 Monate gültiger Reisepass, ein Weiter-/Rückflugnachweis und die Arrival Card","bestMonths":"April bis Mai sowie September bis November"}$j$::jsonb, $j$["Chinesische Mauer – das gewaltige Wahrzeichen, gut erreichbar von Peking","Peking – Verbotene Stadt, Tian'anmen-Platz und Himmelstempel","Terrakotta-Armee in Xi'an – tausende lebensgroße Tonkrieger","Shanghai – futuristische Skyline und die Uferpromenade Bund","Guilin und Yangshuo – traumhafte Karstberge entlang des Li-Flusses","Zhangjiajie – schwebende Felssäulen, Inspiration für „Avatar“","Chengdu – Aufzuchtstation der berühmten Großen Pandas","Huangshan – die malerischen Gelben Berge mit Nebelmeeren"]$j$::jsonb, $j$["Richten Sie schon vor der Reise die Bezahl-Apps Alipay oder WeChat Pay ein und hinterlegen Sie eine ausländische Karte – nahezu alles wird mobil bezahlt, Bargeld ist selten.","Viele westliche Dienste wie Google, WhatsApp und Instagram sind in China gesperrt; eine VPN-App sollte man bereits vor der Einreise installieren.","Das Hochgeschwindigkeitszugnetz ist hervorragend und verbindet die Städte schnell und komfortabel – Tickets bucht man am besten frühzeitig.","Wegen der Sprachbarriere helfen eine Übersetzungs-App mit Offline-Funktion und Adressen in chinesischer Schrift enorm weiter."]$j$::jsonb, $j$[{"question":"Brauche ich ein Visum für China?","answer":"Für touristische Aufenthalte bis zu 30 Tagen können deutsche Staatsbürger derzeit visumfrei einreisen; diese Regelung gilt bis zum 31. Dezember 2026. Nötig sind ein mindestens sechs Monate gültiger Reisepass, ein Nachweis über die Weiter- oder Rückreise sowie die Arrival Card. Da sich die Bestimmungen ändern können, sollte man den aktuellen Stand vorab prüfen."},{"question":"Was ist die Arrival Card?","answer":"Die Arrival Card ist eine verpflichtende Einreisekarte, die man entweder vorab online oder bei der Ankunft auf Papier ausfüllt. Sie gehört zu den Standarddokumenten bei der Einreise nach China."},{"question":"Wann ist die beste Reisezeit für China?","answer":"Am angenehmsten sind Frühling (April bis Mai) und Herbst (September bis November). Der Hochsommer ist heiß und schwül, der Winter im Norden kalt. Die großen Feiertage wie die Golden Week und das chinesische Neujahr sollte man wegen des großen Andrangs meiden."},{"question":"Wie bezahlt man in China?","answer":"China ist weitgehend bargeldlos. Bezahlt wird fast überall mobil per Alipay oder WeChat Pay, in denen sich inzwischen auch ausländische Karten hinterlegen lassen. Diese Apps sollte man vor der Reise einrichten, da Bargeld und ausländische Kreditkarten oft nur eingeschränkt akzeptiert werden."},{"question":"Funktionieren Google, WhatsApp und Co. in China?","answer":"Nein, viele westliche Dienste wie Google, WhatsApp, Instagram und Facebook sind in China gesperrt. Wer sie nutzen möchte, sollte vor der Einreise eine VPN-App installieren, da der Download im Land schwierig sein kann."},{"question":"Wie reist man am besten innerhalb Chinas?","answer":"Das exzellente Hochgeschwindigkeitszugnetz verbindet die Städte schnell und komfortabel; für sehr große Distanzen bieten sich Inlandsflüge an. In den Städten sind Metro und Fahrdienste wie DiDi praktisch. Ein eigener Mietwagen ist nicht zu empfehlen, da ausländische Führerscheine nicht anerkannt werden."},{"question":"Welche Währung gilt in China?","answer":"Die Währung ist der Renminbi, dessen Einheit Yuan (CNY) genannt wird. Im Alltag wird fast ausschließlich mobil bezahlt, weshalb die Einrichtung von Alipay oder WeChat Pay sehr wichtig ist."},{"question":"Spricht man in China Englisch?","answer":"Englisch ist nur wenig verbreitet, vor allem außerhalb großer Hotels und touristischer Orte. Eine Übersetzungs-App, am besten mit Offline-Modus, sowie wichtige Adressen in chinesischer Schrift erleichtern die Verständigung erheblich."},{"question":"Ist China für einen Familienurlaub geeignet?","answer":"Ja, China kann mit Kindern faszinierend sein, etwa durch die Pandas in Chengdu, die Chinesische Mauer und moderne Städte. Wegen Sprache, Distanzen und Bezahlsystemen erfordert eine Familienreise jedoch etwas mehr Planung."},{"question":"Ist China ein sicheres Reiseland?","answer":"Die Kriminalität gegenüber Reisenden ist niedrig, und China gilt als sicher zu bereisen. Beachten sollte man jedoch besondere rechtliche Gegebenheiten und die aktuellen Hinweise des Auswärtigen Amts, etwa zu Registrierungspflichten bei privater Unterkunft."},{"question":"Wie viele Tage sollte man für China einplanen?","answer":"Für die klassischen Höhepunkte Peking, Xi'an und Shanghai sollte man etwa 10 bis 14 Tage einplanen. Wer zusätzlich Naturregionen wie Guilin oder Zhangjiajie und die Pandas in Chengdu erleben möchte, plant 2 bis 3 Wochen ein."}]$j$::jsonb, $t$China Urlaub: Chinesische Mauer, Reisetipps & beste Reisezeit$t$, $t$Dein China-Urlaub: die Chinesische Mauer, die Terrakotta-Armee, Peking und Shanghai, Guilin und die Pandas in Chengdu. Beste Reisezeit, visumfreie Einreise, Highlights und Reisetipps im Überblick.$t$, $t$China Rundreise buchen, Flug nach Peking oder Shanghai, Hotel China, Gruppenreise China, Chinesische Mauer Tour, visumfreie Einreise China$t$, false, $j$["japan","vietnam","thailand"]$j$::jsonb, ARRAY[$t$China$t$,$t$Chinesische Mauer$t$,$t$Peking$t$,$t$Verbotene Stadt$t$,$t$Tian'anmen-Platz$t$,$t$Terrakotta-Armee$t$,$t$Xi'an$t$,$t$Shanghai$t$,$t$Bund$t$,$t$Guilin$t$,$t$Yangshuo$t$,$t$Li-Fluss$t$,$t$Zhangjiajie$t$,$t$Chengdu$t$,$t$Pandas$t$,$t$Renminbi$t$]::text[], $t$China ist ein riesiges Reiseland in Ostasien, bekannt für die Chinesische Mauer, die Verbotene Stadt in Peking, die Terrakotta-Armee in Xi'an, die futuristische Megacity Shanghai, die Karstlandschaften bei Guilin und die Pandas in Chengdu. Für deutsche Reisende ist die Einreise derzeit visumfrei (bis 30 Tage, gültig bis Ende 2026), und dank des hervorragenden Hochgeschwindigkeitszugnetzes lässt sich das Land gut bereisen. Vorbereitung bei Sprache, mobilem Bezahlen mit Alipay/WeChat Pay und Internet (VPN) ist jedoch ratsam.$t$, $t$China ist ein riesiges Reiseland mit der Chinesischen Mauer, der Terrakotta-Armee, Megastädten wie Shanghai und Pandas in Chengdu – für Deutsche derzeit visumfrei bis 30 Tage.$t$, $t$https://www.apearound.de/reiseziele/china$t$, $t$/images/destinations/china.jpg$t$, $t$/images/destinations/china.jpg$t$, $t$China Urlaub: Chinesische Mauer, Reisetipps & beste Reisezeit$t$, $t$Dein China-Urlaub: die Chinesische Mauer, die Terrakotta-Armee, Peking und Shanghai, Guilin und die Pandas in Chengdu. Beste Reisezeit, visumfreie Einreise, Highlights und Reisetipps im Überblick.$t$, $t$China Urlaub: Chinesische Mauer, Reisetipps & beste Reisezeit$t$, $t$Dein China-Urlaub: die Chinesische Mauer, die Terrakotta-Armee, Peking und Shanghai, Guilin und die Pandas in Chengdu. Beste Reisezeit, visumfreie Einreise, Highlights und Reisetipps im Überblick.$t$, $t$draft$t$)
ON CONFLICT (slug) DO NOTHING;

-- Dänemark
INSERT INTO public.destinations (name, slug, country, region, continent, hero_image, short_description, long_description, ai_summary, best_travel_time, ideal_duration, travel_type, quick_facts, highlights, insider_tips, faq, seo_title, seo_description, affiliate_search_intent, car_rental_recommended, similar_destinations, llmo_entities, llmo_answer_block, llmo_quick_answer, canonical_url, open_graph_image, twitter_image, open_graph_title, open_graph_description, twitter_title, twitter_description, status)
VALUES ($t$Dänemark$t$, $t$daenemark$t$, $t$Dänemark$t$, $t$Skandinavien$t$, $t$Europa$t$, $t$/images/destinations/daenemark-hero.jpg$t$, $t$Gemütliches Nachbarland mit dem fahrradfreundlichen Kopenhagen, endlosen Nord- und Ostseestränden, Ferienhäusern, Legoland und viel Hygge.$t$, $t$Dänemark ist für viele Deutsche das Inbegriff entspannten Urlaubs: nah, gemütlich und vielseitig. Die Hauptstadt Kopenhagen begeistert mit dem bunten Hafenviertel Nyhavn, der Kleinen Meerjungfrau, dem traditionsreichen Vergnügungspark Tivoli und einer der weltbesten Fahrradkulturen. Doch das eigentliche Herz des Dänemark-Urlaubs sind die Küsten: An der rauen Nordsee in Westjütland reihen sich weite Sandstrände, Dünen und gemütliche Ferienhäuser aneinander, während die sanftere Ostseeküste und Inseln wie Møn mit ihren weißen Kreidefelsen oder die Sonneninsel Bornholm locken. Familien lieben das originale Legoland in Billund, Kulturfans pilgern in die H.-C.-Andersen-Stadt Odense oder zum Hamlet-Schloss Kronborg. Im Norden, in Skagen, treffen sich zwei Meere am berühmten Grenen. Mit seiner Mischung aus Strand, Natur, Kultur und der typisch dänischen Hygge ist Dänemark ideal für Strand-, Familien- und Städtereisen – und von Deutschland aus besonders schnell erreichbar.$t$, $t$Dänemark ist ein gemütliches Nachbarland mit dem fahrradfreundlichen Kopenhagen, weiten Nord- und Ostseestränden, beliebten Ferienhäusern, dem originalen Legoland und viel Hygge. Es ist von Deutschland aus sehr schnell erreichbar und eignet sich ideal für Strand-, Familien- und Städtereisen.$t$, $t$Mai bis September für Strand, Ferienhausurlaub und mildes Wetter; Kopenhagen ist ganzjährig attraktiv und im Advent besonders stimmungsvoll.$t$, $t$Städtereise 3 bis 4 Tage, Ferienhausurlaub eine Woche oder länger$t$, ARRAY[$t$Städtereise$t$,$t$Strandurlaub$t$,$t$Familien$t$,$t$Radreise$t$,$t$Naturreise$t$,$t$Wochenendtrip$t$,$t$Ferienhausurlaub$t$]::text[], $j${"currency":"Dänische Krone (DKK); Dänemark ist weitgehend bargeldlos","language":"Dänisch; Englisch und oft auch Deutsch sind weit verbreitet","flightTime":"ca. 1 Stunde ab Deutschland (Kopenhagen); sehr gut mit Bahn oder Auto erreichbar","timezone":"MEZ (UTC+1), identisch mit Deutschland","visa":"Nicht erforderlich für EU-Bürger (Schengen-Raum)","bestMonths":"Mai bis September"}$j$::jsonb, $j$["Kopenhagen – Nyhavn, die Kleine Meerjungfrau, Tivoli und Fahrradkultur","Legoland Billund – das originale Legoland, ideal für Familien","Nordseeküste in Westjütland – weite Sandstrände, Dünen und Ferienhäuser","Møns Klint – beeindruckende weiße Kreidefelsen an der Ostsee","Bornholm – die sonnenreiche Ostseeinsel mit Rundkirchen","Skagen – wo Nord- und Ostsee am Grenen aufeinandertreffen","Schloss Kronborg in Helsingør – das berühmte Hamlet-Schloss","Odense – Geburtsstadt des Märchendichters H. C. Andersen"]$j$::jsonb, $j$["Kopenhagen erkundet man am besten wie die Einheimischen mit dem Fahrrad – Leihräder und ein hervorragendes Radwegenetz machen es leicht.","Für einen klassischen Dänemark-Urlaub mietet man ein Ferienhaus an der Nord- oder Ostsee – ideal für Familien und Naturliebhaber.","Unbedingt typische Spezialitäten wie Smørrebrød (belegtes Brot), dänisches Gebäck und einen Hotdog (Pølser) vom Straßenstand probieren.","In Skagen lohnt sich der Ausflug zum Grenen, wo man an der Spitze sehen kann, wie die Wellen zweier Meere aufeinandertreffen."]$j$::jsonb, $j$[{"question":"Welche Währung gilt in Dänemark?","answer":"In Dänemark zahlt man mit der Dänischen Krone (DKK), nicht mit dem Euro. Das Land ist weitgehend bargeldlos, sodass Kartenzahlung und kontaktloses Bezahlen fast überall möglich und üblich sind."},{"question":"Wann ist die beste Reisezeit für Dänemark?","answer":"Für Strand und Ferienhausurlaub eignen sich die Monate Mai bis September am besten. Kopenhagen ist ganzjährig reizvoll und im Advent mit dem weihnachtlichen Tivoli besonders stimmungsvoll."},{"question":"Brauche ich ein Visum für Dänemark?","answer":"Nein. Dänemark ist EU- und Schengen-Mitglied, daher benötigen EU-Bürger kein Visum. Für die Einreise genügt ein gültiger Personalausweis oder Reisepass."},{"question":"Braucht man in Dänemark ein Auto?","answer":"Für Kopenhagen ist ein Auto nicht nötig, da Rad und Nahverkehr hervorragend sind. Für einen Ferienhausurlaub an der Nord- oder Ostsee reisen jedoch viele bequem mit dem eigenen Auto an, da Dänemark direkt an Deutschland grenzt."},{"question":"Ist Dänemark für einen Familienurlaub geeignet?","answer":"Ja, Dänemark ist eines der familienfreundlichsten Reiseländer. Das originale Legoland, kinderfreundliche Strände, Ferienhäuser, Tierparks und der Tivoli machen es zu einem idealen Ziel für Familien."},{"question":"Was ist Hygge?","answer":"Hygge ist ein typisch dänisches Lebensgefühl von Gemütlichkeit, Geborgenheit und bewusstem Genuss kleiner Momente – etwa bei Kerzenschein, gutem Essen und in netter Gesellschaft. Es prägt die dänische Kultur stark."},{"question":"Lohnt sich ein Ferienhausurlaub in Dänemark?","answer":"Auf jeden Fall. Ferienhäuser an der Nord- und Ostsee sind bei deutschen Urlaubern sehr beliebt und bieten viel Platz, Naturnähe und Flexibilität – ideal für Familien und längere Aufenthalte."},{"question":"Spricht man in Dänemark Deutsch oder Englisch?","answer":"Viele Dänen sprechen sehr gut Englisch, und in den grenznahen Regionen sowie touristischen Gebieten oft auch Deutsch. Die Verständigung ist für deutsche Reisende daher unkompliziert."},{"question":"Welche Spezialitäten sollte man in Dänemark probieren?","answer":"Typisch sind Smørrebrød (belegte Brote), dänische Hotdogs (Pølser), Frikadeller, frischer Fisch sowie süßes dänisches Gebäck. Dazu passt ein Kaffee in gemütlicher Hygge-Atmosphäre."},{"question":"Wie viele Tage sollte man für Dänemark einplanen?","answer":"Für einen Städtetrip nach Kopenhagen reichen 3 bis 4 Tage. Für einen Ferienhausurlaub an der Küste oder eine Rundreise sollte man eine Woche oder länger einplanen."}]$j$::jsonb, $t$Dänemark Urlaub: Kopenhagen, Strände, Legoland & beste Reisezeit$t$, $t$Dein Dänemark-Urlaub: Kopenhagen mit Nyhavn und Tivoli, Nord- und Ostseestrände, Ferienhäuser, Legoland und viel Hygge. Beste Reisezeit, Highlights und praktische Reisetipps im Überblick.$t$, $t$Dänemark Urlaub buchen, Ferienhaus Nordsee oder Ostsee Dänemark, Städtereise Kopenhagen, Hotel Kopenhagen, Legoland Billund, Familienurlaub Dänemark$t$, false, $j$["schweden","norwegen","holland"]$j$::jsonb, ARRAY[$t$Dänemark$t$,$t$Kopenhagen$t$,$t$Nyhavn$t$,$t$Kleine Meerjungfrau$t$,$t$Tivoli$t$,$t$Legoland$t$,$t$Billund$t$,$t$Nordseeküste$t$,$t$Westjütland$t$,$t$Møns Klint$t$,$t$Bornholm$t$,$t$Skagen$t$,$t$Grenen$t$,$t$Schloss Kronborg$t$,$t$Odense$t$,$t$Dänische Krone$t$]::text[], $t$Dänemark ist ein gemütliches Nachbarland mit dem fahrradfreundlichen Kopenhagen samt Nyhavn und Tivoli, weiten Nord- und Ostseestränden, beliebten Ferienhäusern, dem originalen Legoland in Billund und viel Hygge. Es ist von Deutschland aus besonders schnell mit Bahn oder Auto erreichbar und eignet sich ideal für Strand-, Familien- und Städtereisen. Die beste Reisezeit für Strand und Ferienhausurlaub liegt zwischen Mai und September.$t$, $t$Dänemark ist ein gemütliches Nachbarland mit dem fahrradfreundlichen Kopenhagen, Nord- und Ostseestränden, Ferienhäusern, Legoland und viel Hygge.$t$, $t$https://www.apearound.de/reiseziele/daenemark$t$, $t$/images/destinations/daenemark.jpg$t$, $t$/images/destinations/daenemark.jpg$t$, $t$Dänemark Urlaub: Kopenhagen, Strände, Legoland & beste Reisezeit$t$, $t$Dein Dänemark-Urlaub: Kopenhagen mit Nyhavn und Tivoli, Nord- und Ostseestrände, Ferienhäuser, Legoland und viel Hygge. Beste Reisezeit, Highlights und praktische Reisetipps im Überblick.$t$, $t$Dänemark Urlaub: Kopenhagen, Strände, Legoland & beste Reisezeit$t$, $t$Dein Dänemark-Urlaub: Kopenhagen mit Nyhavn und Tivoli, Nord- und Ostseestrände, Ferienhäuser, Legoland und viel Hygge. Beste Reisezeit, Highlights und praktische Reisetipps im Überblick.$t$, $t$draft$t$)
ON CONFLICT (slug) DO NOTHING;

-- Dominikanische Republik
INSERT INTO public.destinations (name, slug, country, region, continent, hero_image, short_description, long_description, ai_summary, best_travel_time, ideal_duration, travel_type, quick_facts, highlights, insider_tips, faq, seo_title, seo_description, affiliate_search_intent, car_rental_recommended, similar_destinations, llmo_entities, llmo_answer_block, llmo_quick_answer, canonical_url, open_graph_image, twitter_image, open_graph_title, open_graph_description, twitter_title, twitter_description, status)
VALUES ($t$Dominikanische Republik$t$, $t$dominikanische-republik$t$, $t$Dominikanische Republik$t$, $t$Karibik$t$, $t$Nordamerika$t$, $t$/images/destinations/dominikanische-republik-hero.jpg$t$, $t$Karibik-Klassiker mit palmengesäumten Traumstränden, türkisem Meer, All-Inclusive-Resorts, tropischer Natur und Merengue-Lebensfreude.$t$, $t$Die Dominikanische Republik auf der Insel Hispaniola ist eines der beliebtesten Karibikziele und steht für endlose Sandstrände, Kokospalmen und kristallklares, türkisfarbenes Meer. Besonders die Region rund um Punta Cana und Bávaro ist berühmt für ihre komfortablen All-Inclusive-Resorts und damit ideal für einen unbeschwerten Strand- und Badeurlaub. Doch das Land bietet weit mehr: die grüne Halbinsel Samaná mit Wasserfällen und Walbeobachtung, die vorgelagerte Trauminsel Saona, den Nationalpark Los Haitises mit Mangroven und Höhlen sowie die koloniale Altstadt von Santo Domingo, die zum UNESCO-Weltkulturerbe zählt. Wer Aktivität sucht, findet beim Kitesurfen in Cabarete, beim Canyoning an den Wasserfällen von Damajagua oder beim Wandern auf den Pico Duarte reichlich Abwechslung. Lebensfreude, Merengue- und Bachata-Rhythmen sowie ganzjährig warmes Klima machen das Land zu einem perfekten Ziel für Sonnenhungrige.$t$, $t$Die Dominikanische Republik ist ein beliebtes Karibikziel mit Traumstränden rund um Punta Cana, komfortablen All-Inclusive-Resorts, tropischer Natur auf der Halbinsel Samaná und der kolonialen Altstadt von Santo Domingo. Sie eignet sich ideal für Strand-, Badeurlaub und Erholung, bietet aber auch Aktivurlaub und Kultur.$t$, $t$Die beste Reisezeit ist die Trockenzeit von Dezember bis April; von Juni bis November besteht Hurrikan-Saison. Wale lassen sich vor Samaná von Januar bis März beobachten.$t$, $t$1 bis 2 Wochen$t$, ARRAY[$t$Strandurlaub$t$,$t$All-Inclusive$t$,$t$Pauschalreise$t$,$t$Erholung$t$,$t$Tauchen$t$,$t$Familien$t$,$t$Flitterwochen$t$]::text[], $j${"currency":"Dominikanischer Peso (DOP); in Resorts wird oft auch US-Dollar akzeptiert","language":"Spanisch","flightTime":"ca. 9 bis 10 Stunden ab Deutschland (Punta Cana)","timezone":"UTC−4 (AST), fünf Stunden hinter MEZ; keine Zeitumstellung","visa":"Kein Visum nötig; vor der Reise ist das elektronische E-Ticket (E-Ticket der Einwanderungsbehörde) auszufüllen","bestMonths":"Dezember bis April"}$j$::jsonb, $j$["Punta Cana und Bávaro – weiße Palmenstrände und komfortable All-Inclusive-Resorts","Isla Saona – vorgelagerte Trauminsel mit Postkartenstränden und Naturschutzgebiet","Halbinsel Samaná – grüne Landschaft, Wasserfälle und Walbeobachtung","Nationalpark Los Haitises – Mangroven, Höhlen mit Felsmalereien und Vogelwelt","Santo Domingo – koloniale Altstadt (Zona Colonial) und UNESCO-Weltkulturerbe","Wasserfälle von Damajagua (27 Charcos) – Canyoning und natürliche Rutschen","Cabarete – bekanntes Zentrum für Kite- und Windsurfen","Pico Duarte – mit über 3.000 Metern der höchste Berg der Karibik"]$j$::jsonb, $j$["Wer zwischen Januar und März reist, sollte eine Tour zur Walbeobachtung vor der Halbinsel Samaná einplanen – ein einzigartiges Naturschauspiel.","Mindestens einen Ausflug außerhalb der Resortanlage unternehmen, um das authentische Land mit seinen Dörfern, Märkten und Menschen kennenzulernen.","Den landestypischen Kräuterlikör Mamajuana probieren – er gilt als inoffizielles Nationalgetränk der Dominikanischen Republik.","Abends lohnt es sich, zu Live-Musik Merengue und Bachata zu erleben – Tanz und Rhythmus gehören fest zur dominikanischen Lebensfreude."]$j$::jsonb, $j$[{"question":"Wann ist die beste Reisezeit für die Dominikanische Republik?","answer":"Ideal ist die Trockenzeit von Dezember bis April mit viel Sonne und angenehmer Luftfeuchtigkeit. Von Juni bis November ist Hurrikan-Saison mit höherem Regenrisiko. Wale lassen sich vor Samaná von Januar bis März beobachten."},{"question":"Brauche ich ein Visum für die Dominikanische Republik?","answer":"Ein Visum ist für touristische Aufenthalte nicht erforderlich. Vor der Ein- und Ausreise muss jedoch das elektronische E-Ticket der Einwanderungsbehörde online ausgefüllt werden. Der Reisepass sollte bei Einreise noch gültig sein."},{"question":"Welche Währung gilt in der Dominikanischen Republik?","answer":"Offizielle Währung ist der Dominikanische Peso (DOP). In Resorts und touristischen Gebieten wird häufig auch der US-Dollar akzeptiert. Für Trinkgelder und kleinere Ausgaben empfiehlt sich etwas Bargeld."},{"question":"Wie lange dauert der Flug in die Dominikanische Republik?","answer":"Ein Direktflug von Deutschland nach Punta Cana dauert etwa 9 bis 10 Stunden. Es gibt zahlreiche Direktverbindungen, vor allem in der Hauptsaison im Winter."},{"question":"Ist die Dominikanische Republik sicher?","answer":"Die touristischen Regionen und Resorts gelten als gut bereisbar. Wie in vielen Ländern sollte man Wertsachen sichern, nachts nicht allein abgelegene Gegenden aufsuchen und die aktuellen Reisehinweise des Auswärtigen Amts beachten."},{"question":"Kann man das Leitungswasser trinken?","answer":"Nein, das Leitungswasser ist nicht zum Trinken geeignet. Man sollte auf abgefülltes Wasser zurückgreifen; in den Resorts steht in der Regel ausreichend Trinkwasser zur Verfügung."},{"question":"Lohnt sich ein Mietwagen in der Dominikanischen Republik?","answer":"Die meisten Urlauber bleiben im All-Inclusive-Resort und nutzen organisierte Ausflüge, sodass ein Mietwagen nicht nötig ist. Wer das Land individuell erkunden möchte, kann einen mieten, sollte aber den teils chaotischen Verkehr und den Zustand mancher Straßen einkalkulieren."},{"question":"Welche Impfungen werden empfohlen?","answer":"Vorgeschrieben sind in der Regel keine Impfungen. Empfohlen werden Standardimpfungen sowie je nach Reiseart Hepatitis A. Für eine individuelle Beratung sollte man rechtzeitig den Hausarzt oder ein Tropeninstitut aufsuchen."},{"question":"Ist die Dominikanische Republik für Familien geeignet?","answer":"Ja, viele Resorts sind auf Familien ausgerichtet und bieten flach abfallende Strände, Pools und Animation. Ausflüge wie Bootstouren zur Isla Saona oder zu Wasserfällen sorgen für zusätzliche Abwechslung."},{"question":"Was sollte man kulinarisch probieren?","answer":"Typisch sind La Bandera (Reis, Bohnen und Fleisch), Mofongo aus Kochbananen, frischer Fisch, tropische Früchte sowie der Kräuterlikör Mamajuana. Auch der dominikanische Kaffee und Rum sind einen Versuch wert."},{"question":"Eignet sich das Land für Flitterwochen?","answer":"Ja, mit Traumstränden, romantischen Resorts und Ausflügen zu vorgelagerten Inseln zählt die Dominikanische Republik zu den beliebtesten Zielen für Flitterwochen und Hochzeitsreisen."},{"question":"Wie viel Zeit sollte man einplanen?","answer":"Für einen erholsamen Strandurlaub sind 1 bis 2 Wochen ideal. Wer zusätzlich Natur und Kultur abseits der Resorts erleben möchte, profitiert von der längeren Variante mit mehreren Ausflügen."}]$j$::jsonb, $t$Dominikanische Republik Urlaub: Strände, Tipps & beste Reisezeit$t$, $t$Dein Urlaub in der Dominikanischen Republik: Traumstrände rund um Punta Cana, All-Inclusive-Resorts, Samaná und Santo Domingo. Beste Reisezeit, Highlights und Reisetipps im Überblick.$t$, $t$Dominikanische Republik All-Inclusive buchen, Flug und Hotel Punta Cana, Pauschalreise Karibik, Ausflüge Isla Saona und Samaná, Strandurlaub Dom Rep$t$, false, $j$["kuba","jamaika","mexiko"]$j$::jsonb, ARRAY[$t$Dominikanische Republik$t$,$t$Punta Cana$t$,$t$Bávaro$t$,$t$Isla Saona$t$,$t$Samaná$t$,$t$Los Haitises$t$,$t$Santo Domingo$t$,$t$Zona Colonial$t$,$t$Damajagua$t$,$t$Cabarete$t$,$t$Pico Duarte$t$,$t$Hispaniola$t$,$t$Merengue$t$,$t$Bachata$t$,$t$Mamajuana$t$,$t$Dominikanischer Peso$t$]::text[], $t$Die Dominikanische Republik ist ein beliebtes Karibikziel auf der Insel Hispaniola, bekannt für die Traumstrände rund um Punta Cana, komfortable All-Inclusive-Resorts, die tropische Halbinsel Samaná und die koloniale Altstadt von Santo Domingo. Sie eignet sich ideal für Strand- und Badeurlaub, bietet aber auch Natur, Wassersport und Kultur. Die beste Reisezeit liegt in der Trockenzeit von Dezember bis April.$t$, $t$Die Dominikanische Republik ist ein Karibikziel mit Traumstränden, All-Inclusive-Resorts und tropischer Natur, am besten von Dezember bis April zu bereisen.$t$, $t$https://www.apearound.de/reiseziele/dominikanische-republik$t$, $t$/images/destinations/dominikanische-republik.jpg$t$, $t$/images/destinations/dominikanische-republik.jpg$t$, $t$Dominikanische Republik Urlaub: Strände, Tipps & beste Reisezeit$t$, $t$Dein Urlaub in der Dominikanischen Republik: Traumstrände rund um Punta Cana, All-Inclusive-Resorts, Samaná und Santo Domingo. Beste Reisezeit, Highlights und Reisetipps im Überblick.$t$, $t$Dominikanische Republik Urlaub: Strände, Tipps & beste Reisezeit$t$, $t$Dein Urlaub in der Dominikanischen Republik: Traumstrände rund um Punta Cana, All-Inclusive-Resorts, Samaná und Santo Domingo. Beste Reisezeit, Highlights und Reisetipps im Überblick.$t$, $t$draft$t$)
ON CONFLICT (slug) DO NOTHING;

-- Düsseldorf
INSERT INTO public.destinations (name, slug, country, region, continent, hero_image, short_description, long_description, ai_summary, best_travel_time, ideal_duration, travel_type, quick_facts, highlights, insider_tips, faq, seo_title, seo_description, affiliate_search_intent, car_rental_recommended, similar_destinations, llmo_entities, llmo_answer_block, llmo_quick_answer, canonical_url, open_graph_image, twitter_image, open_graph_title, open_graph_description, twitter_title, twitter_description, status)
VALUES ($t$Düsseldorf$t$, $t$duesseldorf$t$, $t$Deutschland$t$, $t$Nordrhein-Westfalen$t$, $t$Europa$t$, $t$/images/destinations/duesseldorf-hero.jpg$t$, $t$Mondäne Rhein-Metropole mit Luxus-Shopping auf der Kö, lebendiger Altstadt, kreativem MedienHafen und großem Japanviertel.$t$, $t$Düsseldorf, die Landeshauptstadt von Nordrhein-Westfalen, verbindet rheinische Lebensfreude mit großstädtischer Eleganz. Die berühmte Königsallee zählt zu den exklusivsten Einkaufsstraßen Europas, während die historische Altstadt als „längste Theke der Welt“ mit ihren dicht gedrängten Kneipen und dem typischen Altbier für ausgelassene Stimmung sorgt. Architektonisch beeindruckt der MedienHafen mit den geschwungenen Gehry-Bauten, und vom Rheinturm öffnet sich ein weiter Blick über Stadt und Strom. Düsseldorf ist zudem für seine große japanische Gemeinde bekannt – rund um die Immermannstraße findet man authentische Restaurants, Bäckereien und Geschäfte. Mit hochkarätigen Kunstsammlungen, der schönen Rheinuferpromenade und dem barocken Schloss Benrath ist die Stadt ein ideales Ziel für einen abwechslungsreichen Städtetrip.$t$, $t$Düsseldorf ist die Landeshauptstadt von Nordrhein-Westfalen und eine mondäne Rhein-Metropole mit Luxus-Shopping auf der Königsallee, lebendiger Altstadt, dem modernen MedienHafen und einem großen Japanviertel. Die gut erreichbare Stadt eignet sich ideal für einen kompakten Städtetrip rund um Kultur, Kulinarik und Shopping.$t$, $t$Mai bis September für mildes Wetter und Außengastronomie; im Februar lockt der Straßenkarneval, im Juli die große Rheinkirmes.$t$, $t$2 bis 3 Tage$t$, ARRAY[$t$Städtereise$t$,$t$Kulturreise$t$,$t$Shopping$t$,$t$Kulinarik$t$,$t$Paare$t$,$t$Wochenendtrip$t$]::text[], $j${"currency":"Euro (EUR)","language":"Deutsch","flightTime":"Innerdeutsch per Bahn oder Auto erreichbar; internationaler Flughafen Düsseldorf (DUS) mit Verbindungen in ganz Europa","timezone":"MEZ (UTC+1)","visa":"Nicht erforderlich (Inland für Deutsche, EU- und Schengen-Raum)","bestMonths":"Mai bis September"}$j$::jsonb, $j$["Königsallee (die „Kö“) – exklusive Einkaufsstraße mit Wassergraben und Luxusboutiquen","Altstadt – die „längste Theke der Welt“ mit zahlreichen Brauhäusern und Altbier","MedienHafen – moderne Architektur mit den markanten Gehry-Bauten","Rheinturm – Aussichtsplattform mit Panoramablick über Stadt und Rhein","Rheinuferpromenade – beliebte Flaniermeile am Wasser zwischen Altstadt und Hafen","Japanviertel rund um die Immermannstraße – authentische Restaurants und Geschäfte","Schloss Benrath – barockes Lustschloss mit weitläufigem Park","Kunstsammlung Nordrhein-Westfalen (K20 / K21) – bedeutende moderne Kunst"]$j$::jsonb, $j$["In der Altstadt unbedingt ein frisch gezapftes Altbier und den Kräuterlikör Killepitsch probieren – am besten direkt am Tresen eines traditionellen Brauhauses.","Im Japanviertel an der Immermannstraße gibt es authentische Ramen, Sushi und japanische Süßwaren wie sonst kaum anderswo in Deutschland.","Den Sonnenuntergang am besten am MedienHafen oder vom Rheinturm aus genießen, wenn sich die Glasfassaden im Licht spiegeln.","Bei gutem Wetter laden die Rheinwiesen in Oberkassel zu einem entspannten Picknick mit Blick auf die Altstadt-Silhouette ein."]$j$::jsonb, $j$[{"question":"Wann ist die beste Reisezeit für Düsseldorf?","answer":"Am angenehmsten ist Düsseldorf von Mai bis September, wenn die Außengastronomie und die Rheinpromenade zum Verweilen einladen. Für besondere Erlebnisse bieten sich der Karneval im Februar und die Rheinkirmes im Juli an."},{"question":"Wie viele Tage sollte man für Düsseldorf einplanen?","answer":"Für die wichtigsten Sehenswürdigkeiten, einen Altstadtbummel und etwas Shopping reichen 2 bis 3 Tage gut aus. Wer auch Ausflüge ins Umland oder ins benachbarte Köln plant, kann gern länger bleiben."},{"question":"Braucht man in Düsseldorf ein Auto?","answer":"Nein, ein Auto ist nicht nötig. Düsseldorf verfügt über ein sehr gutes Netz aus U-Bahn, Straßenbahn und S-Bahn, und die Innenstadt lässt sich bequem zu Fuß erkunden. Ein Mietwagen lohnt sich nur für Ausflüge ins weitere Umland."},{"question":"Was ist die „längste Theke der Welt“?","answer":"So wird die Düsseldorfer Altstadt genannt, weil sich dort auf engem Raum mehrere Hundert Kneipen, Bars und Brauhäuser aneinanderreihen. Berühmt ist sie für das obergärige Düsseldorfer Altbier."},{"question":"Was kann man in Düsseldorf kostenlos unternehmen?","answer":"Kostenlos sind unter anderem ein Spaziergang über die Rheinuferpromenade, das Flanieren auf der Königsallee, der Park von Schloss Benrath sowie das Bummeln durch die Altstadt und den MedienHafen."},{"question":"Wie kommt man vom Flughafen in die Innenstadt?","answer":"Der Flughafen Düsseldorf (DUS) ist per S-Bahn in rund 10 bis 15 Minuten mit dem Hauptbahnhof verbunden. Alternativ stehen der SkyTrain zur S-Bahn-Station sowie Taxis und Fahrdienste zur Verfügung."},{"question":"Welche Spezialitäten sollte man in Düsseldorf probieren?","answer":"Typisch sind das dunkle Düsseldorfer Altbier, der Kräuterlikör Killepitsch, rheinische Gerichte wie Halve Hahn und Reibekuchen sowie die japanische Küche im Viertel rund um die Immermannstraße."},{"question":"Eignet sich Düsseldorf für einen Familienurlaub?","answer":"Ja, Düsseldorf ist familienfreundlich. Der Aquazoo, der Rheinpark, Schloss Benrath mit Naturkundemuseum und die Rheinkirmes im Sommer bieten viel Abwechslung für Kinder."},{"question":"Was ist der Unterschied zwischen Düsseldorf und Köln?","answer":"Die beiden Rheinstädte gelten als freundschaftliche Rivalen. Düsseldorf ist für Altbier, Mode und das mondäne Flair der Kö bekannt, Köln für Kölsch, den Dom und seinen Karneval. Beide liegen nur etwa eine halbe Stunde voneinander entfernt."},{"question":"Warum gibt es in Düsseldorf ein Japanviertel?","answer":"Düsseldorf beherbergt eine der größten japanischen Gemeinden Europas, da sich viele japanische Unternehmen hier angesiedelt haben. Rund um die Immermannstraße entstand dadurch ein authentisches Viertel mit Restaurants, Geschäften und einem jährlichen Japan-Tag."},{"question":"Ist Düsseldorf ein gutes Ziel zum Shoppen?","answer":"Ja, Düsseldorf zählt zu den besten Shopping-Zielen Deutschlands. Die Königsallee steht für Luxusmarken, während die Schadowstraße und die Altstadt eine große Auswahl an gängigen Geschäften bieten."}]$j$::jsonb, $t$Düsseldorf Städtereise: Sehenswürdigkeiten, Tipps & beste Reisezeit$t$, $t$Dein Städtetrip nach Düsseldorf: Königsallee, Altstadt, MedienHafen und Japanviertel. Die besten Sehenswürdigkeiten, Insidertipps und die ideale Reisezeit im Überblick.$t$, $t$Städtereise Düsseldorf buchen, Hotel Düsseldorf Altstadt oder Kö, Flug nach Düsseldorf, Stadtführungen und Aktivitäten Düsseldorf, Wochenendtrip Rhein$t$, false, $j$["koeln","hamburg","muenchen"]$j$::jsonb, ARRAY[$t$Düsseldorf$t$,$t$Nordrhein-Westfalen$t$,$t$Königsallee$t$,$t$Altstadt Düsseldorf$t$,$t$MedienHafen$t$,$t$Rheinturm$t$,$t$Altbier$t$,$t$Japanviertel$t$,$t$Immermannstraße$t$,$t$Schloss Benrath$t$,$t$Rheinuferpromenade$t$,$t$Kunstsammlung NRW$t$,$t$Rheinkirmes$t$,$t$Killepitsch$t$,$t$Flughafen Düsseldorf$t$]::text[], $t$Düsseldorf ist die Landeshauptstadt von Nordrhein-Westfalen und eine elegante Rhein-Metropole, bekannt für die Luxus-Einkaufsstraße Königsallee, die lebendige Altstadt mit ihrem Altbier, den modernen MedienHafen und ein großes Japanviertel. Die Stadt ist sehr gut erreichbar und eignet sich ideal für einen kompakten Städtetrip rund um Shopping, Kultur und Kulinarik. Innerhalb der Stadt kommt man bequem mit dem dichten Nahverkehrsnetz voran.$t$, $t$Düsseldorf ist die Rhein-Metropole und Landeshauptstadt von NRW, bekannt für die Königsallee, die Altstadt mit Altbier und den MedienHafen.$t$, $t$https://www.apearound.de/reiseziele/duesseldorf$t$, $t$/images/destinations/duesseldorf.jpg$t$, $t$/images/destinations/duesseldorf.jpg$t$, $t$Düsseldorf Städtereise: Sehenswürdigkeiten, Tipps & beste Reisezeit$t$, $t$Dein Städtetrip nach Düsseldorf: Königsallee, Altstadt, MedienHafen und Japanviertel. Die besten Sehenswürdigkeiten, Insidertipps und die ideale Reisezeit im Überblick.$t$, $t$Düsseldorf Städtereise: Sehenswürdigkeiten, Tipps & beste Reisezeit$t$, $t$Dein Städtetrip nach Düsseldorf: Königsallee, Altstadt, MedienHafen und Japanviertel. Die besten Sehenswürdigkeiten, Insidertipps und die ideale Reisezeit im Überblick.$t$, $t$draft$t$)
ON CONFLICT (slug) DO NOTHING;

-- England
INSERT INTO public.destinations (name, slug, country, region, continent, hero_image, short_description, long_description, ai_summary, best_travel_time, ideal_duration, travel_type, quick_facts, highlights, insider_tips, faq, seo_title, seo_description, affiliate_search_intent, car_rental_recommended, similar_destinations, llmo_entities, llmo_answer_block, llmo_quick_answer, canonical_url, open_graph_image, twitter_image, open_graph_title, open_graph_description, twitter_title, twitter_description, status)
VALUES ($t$England$t$, $t$england$t$, $t$Vereinigtes Königreich$t$, $t$Westeuropa$t$, $t$Europa$t$, $t$/images/destinations/england-hero.jpg$t$, $t$Geschichtsträchtiges Land mit der Weltmetropole London, royalen Schlössern, malerischen Cotswold-Dörfern, dem Lake District und britischer Pub-Kultur.$t$, $t$England, der größte Landesteil des Vereinigten Königreichs, vereint pulsierende Metropolen, jahrhundertealte Geschichte und idyllische Landschaften. Im Zentrum steht London – eine der spannendsten Städte der Welt mit Wahrzeichen wie Big Ben, dem Tower, dem Buckingham Palace und einer Vielzahl weltberühmter, oft kostenloser Museen. Außerhalb der Hauptstadt erwarten Reisende die geheimnisvollen Steinkreise von Stonehenge, die honigfarbenen Dörfer der Cotswolds, die romantischen Seen und Berge des Lake District sowie die altehrwürdigen Universitätsstädte Oxford und Cambridge. Geschichtsträchtige Orte wie das römische Bath, das mittelalterliche York und royale Schlösser wie Windsor runden das Bild ab. Im Südwesten lockt die raue Küste Cornwalls. Dazu gehören typisch britische Erlebnisse wie ein Pub-Besuch, ein Sunday Roast oder der klassische Afternoon Tea. England ist von Deutschland aus schnell erreichbar und ideal für Städtereisen, Roadtrips und Kulturtrips.$t$, $t$England ist der größte Landesteil des Vereinigten Königreichs mit der Weltmetropole London, historischen Stätten wie Stonehenge, royalen Schlössern, den Cotswolds und dem Lake District. Es eignet sich ideal für Städtereisen, Kulturtrips und Roadtrips und ist von Deutschland aus schnell erreichbar. Für die Einreise sind ein Reisepass und eine elektronische Reisegenehmigung (ETA) nötig.$t$, $t$Mai bis September für mildes Wetter und lange Tage; London ist ganzjährig attraktiv, besonders stimmungsvoll auch in der Vorweihnachtszeit.$t$, $t$Städtereise 3 bis 4 Tage, Rundreise rund eine Woche$t$, ARRAY[$t$Städtereise$t$,$t$Kulturreise$t$,$t$Roadtrip$t$,$t$Naturreise$t$,$t$Geschichtsreise$t$,$t$Familien$t$]::text[], $j${"currency":"Britisches Pfund (GBP)","language":"Englisch","flightTime":"ca. 1,5 Stunden ab Deutschland (London)","timezone":"GMT (UTC+0), eine Stunde hinter MEZ","visa":"Kein Visum nötig, aber Reisepass und vorab eine kostenpflichtige elektronische Reisegenehmigung (ETA) erforderlich","bestMonths":"Mai bis September"}$j$::jsonb, $j$["London – Big Ben, Tower of London, Buckingham Palace und weltberühmte Museen","Stonehenge – prähistorischer Steinkreis und UNESCO-Welterbe","Cotswolds – malerische Dörfer aus honigfarbenem Stein","Lake District – romantische Seen- und Berglandschaft im Nordwesten","Oxford und Cambridge – altehrwürdige Universitätsstädte","Bath – römische Thermen und elegante georgianische Architektur","York – mittelalterliche Stadtmauern und das beeindruckende York Minster","Cornwall – raue Küsten, Strände und malerische Fischerdörfer"]$j$::jsonb, $j$["In London am besten kontaktlos mit Karte oder Smartphone bezahlen oder eine Oyster Card nutzen – das ist günstiger und einfacher als Einzeltickets.","Viele der besten Museen Londons wie das British Museum, die National Gallery und das Natural History Museum sind kostenlos zugänglich.","Das Wetter ist wechselhaft – wer in mehreren Schichten und mit einer leichten Regenjacke unterwegs ist, bleibt für jede Lage gewappnet.","Typisch britische Erlebnisse wie ein Sunday Roast im Pub oder ein klassischer Afternoon Tea gehören bei einem England-Besuch unbedingt dazu."]$j$::jsonb, $j$[{"question":"Brauche ich für England ein Visum?","answer":"Für touristische Aufenthalte benötigen deutsche Staatsbürger kein Visum, jedoch seit der Einführung der Regelung eine kostenpflichtige elektronische Reisegenehmigung (ETA), die vor der Reise online beantragt werden muss. Zudem ist ein gültiger Reisepass erforderlich; der Personalausweis reicht seit dem Brexit nicht mehr aus."},{"question":"Was ist die ETA für England?","answer":"Die ETA (Electronic Travel Authorisation) ist eine elektronische Einreisegenehmigung, die visumfreie Besucher – darunter EU-Bürger – vor der Reise ins Vereinigte Königreich online beantragen müssen. Sie ist kostenpflichtig, gilt für mehrere Einreisen und sollte rechtzeitig vor Abflug beantragt werden."},{"question":"Welche Währung gilt in England?","answer":"In England zahlt man mit dem Britischen Pfund (GBP), nicht mit dem Euro. Kartenzahlung und kontaktloses Bezahlen sind nahezu überall möglich und üblich."},{"question":"Wann ist die beste Reisezeit für England?","answer":"Am angenehmsten ist es von Mai bis September mit milderem Wetter und langen Tagen. London ist ganzjährig reizvoll und in der Vorweihnachtszeit besonders stimmungsvoll. Das Wetter bleibt jedoch zu jeder Jahreszeit wechselhaft."},{"question":"Fährt man in England links?","answer":"Ja, in England herrscht Linksverkehr. Wer einen Mietwagen nutzt, sollte sich darauf einstellen, besonders an Kreisverkehren und Kreuzungen. In London ist ein Auto wegen des dichten Verkehrs und der City-Maut (Congestion Charge) nicht zu empfehlen."},{"question":"Lohnt sich ein Mietwagen in England?","answer":"Für London ist ein Auto nicht nötig, da der öffentliche Nahverkehr hervorragend ist. Für ländliche Regionen wie die Cotswolds, den Lake District oder Cornwall ist ein Mietwagen jedoch sehr praktisch – unter Berücksichtigung des Linksverkehrs."},{"question":"Sind die Museen in London wirklich kostenlos?","answer":"Viele der bedeutendsten Museen sind tatsächlich kostenlos, darunter das British Museum, die National Gallery, die Tate Modern und das Natural History Museum. Für Sonderausstellungen und Attraktionen wie den Tower of London fallen hingegen Eintrittsgebühren an."},{"question":"Wie komme ich am besten nach England?","answer":"Am schnellsten reist man per Flug nach London (rund 1,5 Stunden) oder andere englische Städte. Alternativ ist die Anreise mit dem Eurostar-Zug über Paris oder Brüssel sowie per Fähre über den Ärmelkanal möglich."},{"question":"Ist England für einen Familienurlaub geeignet?","answer":"Ja, England ist sehr familienfreundlich. London bietet kostenlose Museen, Parks und Attraktionen wie das London Eye, dazu locken Erlebnisse wie die Harry-Potter-Studios, Schlösser und die Küste Cornwalls."},{"question":"Welche Spezialitäten sollte man in England probieren?","answer":"Typisch sind Fish and Chips, der Sunday Roast, ein English Breakfast, Scones mit Clotted Cream beim Afternoon Tea sowie Pub-Klassiker wie Pies. Die Esskultur ist heute vielfältiger und besser als ihr Ruf."},{"question":"Wie viele Tage sollte man für England einplanen?","answer":"Für London allein sind 3 bis 4 Tage ideal. Wer zusätzlich Stonehenge, Bath, die Cotswolds oder den Lake District erleben möchte, sollte für eine Rundreise rund eine Woche oder mehr einplanen."}]$j$::jsonb, $t$England Urlaub: London, Sehenswürdigkeiten, Tipps & beste Reisezeit$t$, $t$Dein England-Urlaub: London, Stonehenge, die Cotswolds, der Lake District und royale Schlösser. Beste Reisezeit, Einreise mit ETA, Highlights und praktische Reisetipps im Überblick.$t$, $t$England Reise buchen, Flug und Hotel London, Städtereise London, Mietwagen England vergleichen, Rundreise England, Ferienhaus Cornwall oder Cotswolds$t$, true, $j$["schottland","irland","frankreich"]$j$::jsonb, ARRAY[$t$England$t$,$t$Vereinigtes Königreich$t$,$t$London$t$,$t$Big Ben$t$,$t$Tower of London$t$,$t$Buckingham Palace$t$,$t$Stonehenge$t$,$t$Cotswolds$t$,$t$Lake District$t$,$t$Oxford$t$,$t$Cambridge$t$,$t$Bath$t$,$t$York$t$,$t$Cornwall$t$,$t$Britisches Pfund$t$,$t$ETA$t$]::text[], $t$England ist der größte Landesteil des Vereinigten Königreichs mit der Weltmetropole London, historischen Stätten wie Stonehenge, royalen Schlössern, den malerischen Cotswolds und dem Lake District. Es eignet sich ideal für Städtereisen, Kulturtrips und Roadtrips und ist von Deutschland aus in rund 1,5 Stunden erreichbar. Für die Einreise sind ein Reisepass und eine vorab beantragte elektronische Reisegenehmigung (ETA) nötig; gezahlt wird mit dem Britischen Pfund.$t$, $t$England ist ein geschichtsträchtiges Land mit der Metropole London, Stonehenge, den Cotswolds und dem Lake District; zur Einreise braucht man Reisepass und ETA.$t$, $t$https://www.apearound.de/reiseziele/england$t$, $t$/images/destinations/england.jpg$t$, $t$/images/destinations/england.jpg$t$, $t$England Urlaub: London, Sehenswürdigkeiten, Tipps & beste Reisezeit$t$, $t$Dein England-Urlaub: London, Stonehenge, die Cotswolds, der Lake District und royale Schlösser. Beste Reisezeit, Einreise mit ETA, Highlights und praktische Reisetipps im Überblick.$t$, $t$England Urlaub: London, Sehenswürdigkeiten, Tipps & beste Reisezeit$t$, $t$Dein England-Urlaub: London, Stonehenge, die Cotswolds, der Lake District und royale Schlösser. Beste Reisezeit, Einreise mit ETA, Highlights und praktische Reisetipps im Überblick.$t$, $t$draft$t$)
ON CONFLICT (slug) DO NOTHING;

-- Frankreich
INSERT INTO public.destinations (name, slug, country, region, continent, hero_image, short_description, long_description, ai_summary, best_travel_time, ideal_duration, travel_type, quick_facts, highlights, insider_tips, faq, seo_title, seo_description, affiliate_search_intent, car_rental_recommended, similar_destinations, llmo_entities, llmo_answer_block, llmo_quick_answer, canonical_url, open_graph_image, twitter_image, open_graph_title, open_graph_description, twitter_title, twitter_description, status)
VALUES ($t$Frankreich$t$, $t$frankreich$t$, $t$Frankreich$t$, $t$Westeuropa$t$, $t$Europa$t$, $t$/images/destinations/frankreich-hero.jpg$t$, $t$Das Land der Lebenskunst mit dem glanzvollen Paris, der Côte d'Azur, der Provence mit Lavendelfeldern, Loire-Schlössern, exzellenter Küche und großen Weinen.$t$, $t$Frankreich ist eines der vielfältigsten und beliebtesten Reiseländer der Welt und der Inbegriff von Lebensart, Genuss und Kultur. Die Hauptstadt Paris verzaubert mit dem Eiffelturm, dem Louvre, dem Künstlerviertel Montmartre und der wiedereröffneten Kathedrale Notre-Dame. Im Süden lockt die glamouröse Côte d'Azur mit Nizza, Cannes und Saint-Tropez, während die Provence mit lavendelduftenden Feldern, malerischen Dörfern und Städten wie Avignon und Aix-en-Provence betört. Das Loire-Tal beeindruckt mit prachtvollen Königsschlössern, die Normandie mit dem märchenhaften Mont-Saint-Michel und den geschichtsträchtigen D-Day-Stränden, die Bretagne mit rauer Küste. Weinliebhaber pilgern nach Bordeaux, ins Burgund und in die Champagne, Bergfreunde in die französischen Alpen rund um den Mont Blanc. Dazu kommen Familienziele wie Disneyland Paris und die wilde Insel Korsika. Frankreich ist ideal für Städte-, Kultur-, Genuss- und Rundreisen – im Landesinneren am schönsten als Roadtrip mit dem Mietwagen.$t$, $t$Frankreich ist ein vielfältiges Reiseland mit dem glanzvollen Paris, der Côte d'Azur, der Provence mit Lavendelfeldern, den Loire-Schlössern, dem Mont-Saint-Michel sowie weltberühmter Küche und großen Weinen. Es eignet sich ideal für Städte-, Kultur-, Genuss- und Rundreisen und ist von Deutschland aus schnell erreichbar.$t$, $t$April bis Oktober ist allgemein ideal; die Côte d'Azur und die Strände sind im Sommer am schönsten, Paris im Frühling und Herbst, die Lavendelblüte der Provence erlebt man im Juni und Juli.$t$, $t$Städtereise 3 bis 4 Tage, Rundreise 1 bis 2 Wochen$t$, ARRAY[$t$Städtereise$t$,$t$Kulturreise$t$,$t$Strandurlaub$t$,$t$Roadtrip$t$,$t$Kulinarik$t$,$t$Wein$t$,$t$Familien$t$,$t$Rundreise$t$]::text[], $j${"currency":"Euro (EUR)","language":"Französisch","flightTime":"ca. 1,5 bis 2 Stunden ab Deutschland (Paris); gut mit Bahn (TGV) oder Auto erreichbar","timezone":"MEZ (UTC+1), identisch mit Deutschland","visa":"Nicht erforderlich für EU-Bürger (Schengen-Raum)","bestMonths":"April bis Oktober"}$j$::jsonb, $j$["Paris – Eiffelturm, Louvre, Montmartre und die wiedereröffnete Notre-Dame","Côte d'Azur – die glamouröse Riviera mit Nizza, Cannes und Saint-Tropez","Provence – Lavendelfelder, malerische Dörfer, Avignon und Aix-en-Provence","Loire-Tal – prachtvolle Königsschlösser, UNESCO-Welterbe","Mont-Saint-Michel – die spektakuläre Klosterinsel in der Normandie","Normandie und Bretagne – raue Küsten und die historischen D-Day-Strände","Weinregionen – Bordeaux, Burgund und die Champagne","Französische Alpen – Mont Blanc und Chamonix für Berg und Wintersport"]$j$::jsonb, $j$["Die Kathedrale Notre-Dame in Paris ist nach dem Brand seit Ende 2024 wiedereröffnet und definitiv einen Besuch wert – wegen des Andrangs lohnt sich frühes Kommen.","Die Lavendelfelder der Provence blühen vor allem im Juni und Juli, am bekanntesten rund um das Plateau de Valensole.","Das Loire-Tal mit seinen Schlössern erkundet man ideal per Mietwagen oder gemütlich mit dem Fahrrad.","Zwischen den Städten ist der TGV-Hochgeschwindigkeitszug sehr schnell; in Paris selbst nutzt man am besten die Metro statt eines Autos."]$j$::jsonb, $j$[{"question":"Wann ist die beste Reisezeit für Frankreich?","answer":"Allgemein ist April bis Oktober ideal. Die Côte d'Azur und die Strände sind im Sommer am schönsten, Paris im Frühling und Herbst, und die Lavendelblüte der Provence erlebt man im Juni und Juli."},{"question":"Welche Währung gilt in Frankreich?","answer":"In Frankreich zahlt man mit dem Euro (EUR). Kartenzahlung ist weit verbreitet, etwas Bargeld ist für kleine Cafés, Märkte und Bäckereien praktisch."},{"question":"Brauche ich ein Visum für Frankreich?","answer":"Nein. Frankreich ist EU- und Schengen-Mitglied, daher benötigen EU-Bürger kein Visum. Für die Einreise genügt ein gültiger Personalausweis oder Reisepass."},{"question":"Braucht man in Frankreich ein Auto?","answer":"Für Paris und andere Städte ist ein Auto nicht nötig, da Metro und der TGV hervorragend sind. Für Regionen wie die Provence, das Loire-Tal, die Dordogne oder die Bretagne ist ein Mietwagen jedoch ideal."},{"question":"Was sollte man in Paris unbedingt sehen?","answer":"Zu den Höhepunkten zählen der Eiffelturm, der Louvre, die wiedereröffnete Notre-Dame, der Triumphbogen mit den Champs-Élysées, das Künstlerviertel Montmartre und ein Bummel entlang der Seine."},{"question":"Wann blüht der Lavendel in der Provence?","answer":"Die Lavendelfelder blühen meist von Mitte Juni bis Mitte/Ende Juli, abhängig von Höhenlage und Wetter. Besonders bekannt sind die Felder auf dem Plateau de Valensole und rund um die Abtei Sénanque."},{"question":"Ist Frankreich für einen Familienurlaub geeignet?","answer":"Ja, Frankreich ist sehr familienfreundlich. Disneyland Paris, kinderfreundliche Strände an der Atlantik- und Mittelmeerküste, Schlösser und Freizeitparks wie der Puy du Fou bieten viel Abwechslung."},{"question":"Spricht man in Frankreich Englisch?","answer":"In Paris und touristischen Regionen kommt man mit Englisch meist zurecht. Abseits davon sind die Kenntnisse unterschiedlich; ein paar französische Höflichkeitsfloskeln werden sehr geschätzt und öffnen viele Türen."},{"question":"Welche kulinarischen Spezialitäten sollte man probieren?","answer":"Frankreich ist ein Paradies für Genießer: frische Croissants und Baguettes, Käsespezialitäten, Crêpes, regionale Gerichte wie Bouillabaisse oder Coq au Vin sowie die großen Weine aus Bordeaux, Burgund und der Champagne."},{"question":"Wie viele Tage sollte man für Frankreich einplanen?","answer":"Für eine Stadt wie Paris reichen 3 bis 4 Tage. Wer mehrere Regionen wie die Provence, die Côte d'Azur oder das Loire-Tal verbinden möchte, sollte 1 bis 2 Wochen einplanen."}]$j$::jsonb, $t$Frankreich Urlaub: Paris, Provence, Côte d'Azur & beste Reisezeit$t$, $t$Dein Frankreich-Urlaub: Paris mit Eiffelturm und Notre-Dame, die Côte d'Azur, die Provence mit Lavendelfeldern und die Loire-Schlösser. Beste Reisezeit, Highlights und praktische Reisetipps im Überblick.$t$, $t$Frankreich Reise buchen, Städtereise Paris, Flug nach Paris oder Nizza, Hotel Paris, Mietwagen Frankreich, Ferienhaus Provence oder Côte d'Azur, Rundreise Frankreich$t$, true, $j$["italien","spanien","belgien"]$j$::jsonb, ARRAY[$t$Frankreich$t$,$t$Paris$t$,$t$Eiffelturm$t$,$t$Louvre$t$,$t$Notre-Dame$t$,$t$Montmartre$t$,$t$Côte d'Azur$t$,$t$Nizza$t$,$t$Provence$t$,$t$Lavendelfelder$t$,$t$Loire-Tal$t$,$t$Mont-Saint-Michel$t$,$t$Normandie$t$,$t$Bordeaux$t$,$t$Mont Blanc$t$,$t$Euro$t$]::text[], $t$Frankreich ist eines der vielfältigsten Reiseländer der Welt mit dem glanzvollen Paris samt Eiffelturm, Louvre und der wiedereröffneten Notre-Dame, der glamourösen Côte d'Azur, der Provence mit Lavendelfeldern, den Loire-Schlössern und dem Mont-Saint-Michel. Berühmt für seine Küche und großen Weine, eignet es sich ideal für Städte-, Kultur-, Genuss- und Rundreisen und ist von Deutschland aus schnell erreichbar. Die beste Reisezeit liegt je nach Region zwischen April und Oktober.$t$, $t$Frankreich begeistert mit Paris, der Côte d'Azur, der Provence mit Lavendelfeldern, Loire-Schlössern sowie weltberühmter Küche und großen Weinen.$t$, $t$https://www.apearound.de/reiseziele/frankreich$t$, $t$/images/destinations/frankreich.jpg$t$, $t$/images/destinations/frankreich.jpg$t$, $t$Frankreich Urlaub: Paris, Provence, Côte d'Azur & beste Reisezeit$t$, $t$Dein Frankreich-Urlaub: Paris mit Eiffelturm und Notre-Dame, die Côte d'Azur, die Provence mit Lavendelfeldern und die Loire-Schlösser. Beste Reisezeit, Highlights und praktische Reisetipps im Überblick.$t$, $t$Frankreich Urlaub: Paris, Provence, Côte d'Azur & beste Reisezeit$t$, $t$Dein Frankreich-Urlaub: Paris mit Eiffelturm und Notre-Dame, die Côte d'Azur, die Provence mit Lavendelfeldern und die Loire-Schlösser. Beste Reisezeit, Highlights und praktische Reisetipps im Überblick.$t$, $t$draft$t$)
